import ImportService from"../Service/ImportService.js";export default class TemplateService{constructor(){this._templateName="Classic";this._template=null}get templateName(){return this._templateName}set templateName(value){value=value.charAt(0).toUpperCase()+value.slice(1).toLowerCase();this._templateName=value}get template(){return this._template}set template(value){this._template=value}async loadTemplate(){const templateIndex=await ImportService.importWithLastModified("../Template/index.js");let template=new templateIndex[this._templateName];this._template=template;return template}renderForm(selector){const oldEl=document.querySelector(selector);const wrapper=document.createElement("div");wrapper.id=selector.replace("#","");wrapper.innerHTML=this._template.getForm(selector);oldEl.parentNode.replaceChild(wrapper,oldEl);return this}renderRow(selector,entity,json){const template=this._template;const containerContent=document.querySelector(selector+" .dyjsform_container").innerHTML;let rows=json;let HtmlForm=containerContent;rows.forEach(((row,rowIndex)=>{HtmlForm+=template.getBegin();HtmlForm+=this.fieldRender(entity,row,rowIndex);HtmlForm+=template.getEnd()}));document.querySelector(selector+" .dyjsform_container").innerHTML=HtmlForm;return this}assignBootstrapCols(entities){const flexValues=entities.map((e=>e.flex||1));const totalFlex=flexValues.reduce(((sum,f)=>sum+f),0);const exactCols=flexValues.map((f=>f/totalFlex*12));let cols=exactCols.map((c=>Math.floor(c)));const decimals=exactCols.map(((exact,i)=>({index:i,decimal:exact-cols[i]})));let remainingCols=12-cols.reduce(((sum,c)=>sum+c),0);decimals.sort(((a,b)=>b.decimal-a.decimal));for(let i=0;i<remainingCols;i++){cols[decimals[i].index]++}entities.forEach(((e,i)=>e.bsColSize=cols[i]));return entities}fieldRender(entity,row,rowIndex){const totalFieldsCount=entity.length;const template=this._template;row=this.assignBootstrapCols(row);let Html="";for(let field of row){Html+=template.getField(field,rowIndex,totalFieldsCount)}return Html}injectCSS(){var style=document.createElement("style");style.textContent=this._template.getCss();style.setAttribute("data-dyjsform-stylesheet","");var head=document.head;var firstStyleOrLinkTag=document.querySelector("head>style,head>link");if(firstStyleOrLinkTag){head.insertBefore(style,firstStyleOrLinkTag)}else{head.appendChild(style)}return this}}